    "나는 여기 온 뒤로 한 번도 바다에 들어가고 싶다는 생각을 안 했지만 지금 이 순간에 어쩐 일인지 옷을 벗어 버리고 싶었어요.",
    "요즘은 인터넷만 뒤지면 모든 정보와 지식와 호수 그 바다에 풍덩 빠질 수 있을 수 정도로 그런 시대예요.",
    "어떤 사람들은 람세스 2세는 6명의 아내와 100명 이상의 자녀가 있었다고 말한다.",
    "사무총장은 전쟁 중인 두 파벌 간에 평화조약을 협상하기 위해서 필사적으로 노력하고 있다.",
    "학교에 가기도 했고, 비밀 산타에게 주기 위해 선물을 사기도 하고, 급우에게 목도리를 줬는데 얘도 목도리 줬네, 우연의 일치지!",
    "날씨가 나빠도 장점 하나는 있지, 일기쓰기를 계속할 수 있고 스페인어 수준도 끌어올릴 수 있겠다.",
    "크리스토퍼 콜럼버스의 배만큼 두껍고 세 배나 넓은 크기를 가진 신화 속 괴물인 크라켄은 그의 함선을 공격했고, 결국 콜럼버스는 그 괴물을 먹을 수 밖에 없었어.",
    "결국에 우리의 기억에 남는 것은, 적들의 말이 아닌 친구의 침묵이 될것이다.",
    "내 남편은 아픈 이후로 20 킬로가 빠졌고 남편이 입는 바지는 이제 완전히 헐렁하다.",
    "\"너 쿠키 얼마나 샀어?\" \"세 봉지 샀는데, 근데 이제 더 이상 없어. 그냥 맛만 보려고 했을 뿐인데, 그러다가 너무 맛있어서 주체할 수 없었거든.\"",
    "이 수프 괜찮은 것 같아. 네가 식탁에 올려도 되겠는데. 난 채소가 좀 아삭한 채로 너무 푹 익지 않은 게 좋더라.",
    "\"이거 가정집 요리예요?\" 나는 종업원에게 질문을 던졌다. \"네.\" 종업원은 싱긋 웃으며 대답했다. 그야 물론 집에서도 차려지는 요리이기는 했다. 공장에서 미리 조리되었다는 사실만큼은 침묵으로 지켜졌다.",
    "내가 C 수업을 처음 들었을 때, 난 강의 내용의 한 글자도 이해를 못 했었어. 진짜 다행스럽게도 나한텐 모든 것이 어떻게 작동하는지 알려줄 수 있는 프로그래머 친구를 뒀지 뭐야.",
    "톰은 오히려 비호감인 것 같아. 더 나은 표현으로 말하자면, 톰의 정치적 사상이 경악스럽다고도 할 수 있겠네.",
    "톰은 타인에게 비난을 좀 자주 해. 톰은 거울 좀 가끔씩 봐야할 것 같아.",
    "그 사람은 막 중국어 배우기를 시작했음에도 불구하고 이미 많은 글자를 알고 있어.",
    "뼈, 근육 안 쑤시는 곳이 없네. 오늘 너무 힘든 날이었는데, 그래도 엄청 재미있었어.",
    "만일 네 사정도 잘 모르는 사람이 원어민 같다고 말한다면 그건 그 사람이 네가 원어민이 아니라고 깨닫게 해주는 뭔가를 네 말 속에서 캐치해 낸 것이겠지. 다르게 표현하자면 넌 원어민처럼 말하지 않아.",
    "깼다고 생각하면 그건 아직 꿈속에서... 깼다고 생각하면 그건 아직 꿈속에서...",
    "\"왜 날 파티에 초대하지 않은 거야?\" \"초대했어! 이메일 못 본 거야?\"",
    "마음에 드는 돌멩이를 집었으면, 얼른 집으로 가져가 잘 돌보도록 한다. 그게 그대의 유일한 돌멩이이기 때문이다.",
    "타토에바에는 어딘가 이상한 문장이 종종 보이는데, 그런 문장을 발견하면 웃음이 나와.",
    "성공할 가능성이 조금이라도 있다면 탄핵 절차를 밟기를 최대한 빨리 시작해야 한다.",
    "시민들은 하루종일 일하고도 밤마다 주말마다 광장으로 나오는데 누구는 따뜻한 집에서 게으르게 누워있다더라.",
    "오랜만에 영화를 보러 갔는데, 생각했던 것 이상으로 감동해서 눈물이 나왔다.",
    "\"배고프다. 뭔가 없어?\" \"컵라면이라면 있는데 먹을래?\" \"응. 먹을래.\"",
    "어려운 개념도 구체적인 예시나 시각적인 자료를 활용해 설명하고, 알기 쉬움을 중시한다.",
    "\"'카놀라유'는 '유채'에서 얻을 수 있지?\" \"아마도.\" \"그러면 '유채'와 '평지'는 같은 거였나?\" \"같은 거 아니야?\"",
    "지금이야말로 결정적인 순간입니다. 아직도 너무 고집스럽게 굳어 있지 말고, 임기응변을 전혀 못하는 상태가 되지 않도록 해 주세요.",
    "이 영화는 고정관념을 깨고, 진정한 남성다움이 무엇인지 다시 정의하려 한다.",
    "태양계에는 네 개의 기체 거대 행성이 있어요: 목성, 토성, 천왕성, 해왕성.",
    "신주를 여행할 때는 청화대와 교통대 캠퍼스의 아름다운 경치를 놓치지 말아야 한다.",
    "사람들은 \"남성은 여성 화장실에 들어갈 수 없습니다\"라고 쓰인 표지판을 들고 있었다.",
    "처음에 법의학 팀은 사람의 피를 발견했다고 생각했지만, 나중에 실험실에서 그것이 사실 소의 피라는 것을 알게 되었다.",
    "계곡 속에서 엷은 안개가 흰 깃털처럼 천천히 피어올라 한 덩어리의 흰 구름이 되어 모든 것을 가려버렸다.",
    "1월, 2월, 3월, 4월, 5월, 6월, 7월, 8월, 9월, 10월, 11월, 12월.",
